import { createTheme } from "@mui/material/styles";

const theme = createTheme({
  palette: {
    primary: {
      main: "#006060",
    },
    secondary: {
      main: "#ebcea0",
    },
    background: {
      default: "#f0f0d8",
    },
  },
  typography: {
    fontFamily: "Oranienbaum, sans-serif",
  },
});

export default theme;
